// Lazy, process-wide-singleton loader for `glm`'s compiled wasm module --
// same pattern as `src/alerts/wasmModule.ts`. Generated by
// `scripts/build-wasm.mjs`; loaded only once lightning is switched on.
import init, { decodeGlmFlashes } from "../wasm/glm.js";

export { decodeGlmFlashes };

let modulePromise: Promise<void> | null = null;

/** Ensure the `glm` wasm module is instantiated. Safe to call more than once. */
export function ensureGlmWasmModuleLoaded(): Promise<void> {
  if (!modulePromise) {
    modulePromise = init().then(() => undefined);
  }
  return modulePromise;
}
